output:
 * Name: nxcameraer_jointhread
 ****************************************************************************/

static void nxcamera_jointhread(FAR struct nxcamera_s *pcam)
{
  FAR void *value;
  int id = 0;

  if (gettid() == pcam->loop_id)
    {
      return;
    }

  pthread_mutex_lock(&pcam->mutex);

  if (pcam->loop_id > 0)
    {
      id = pcam->loop_id;
      pcam->loop_id = 0;
    }

  pthread_mutex_unlock(&pcam->mutex);

  if (id > 0)
    {
      pthread_join(id, &value);
    }
}

/****************************************************************************
 * Name: nxcamera_loopthread
 *
 *  This is the thread that streams the video and handles video controls.
 *
 ****************************************************************************/

static void *nxcamera_loopthread(pthread_addr_t pvarg)
{
  FAR struct nxcamera_s   *pcam = (FAR struct nxcamera_s *)pvarg;
  unsigned int            prio;
  ssize_t                 size;
  struct video_msg_s      msg;
  bool                    streaming = true;
  int                     output_fd = -1;
  int                     i;
  int                     ret;
  struct v4l2_buffer      buf;
  uint32_t                type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

  vinfo("Entry\n");
  memset(&buf, 0, sizeof(buf));
  for (i = 0; i < pcam->nbuffers; i++)
    {
      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      buf.memory = V4L2_MEMORY_MMAP;
      buf.index = i;
      ret = ioctl(pcam->capture_fd, VIDIOC_QBUF, (uintptr_t)&buf);
      if (ret < 0)
        {
          verr("VIDIOC_QBUF failed: %d\n", ret);
          goto err_out;
        }
    }

  /* VIDIOC_STREAMON start stream */

  ret = ioctl(pcam->capture_fd, VIDIOC_STREAMON, (uintptr_t)&type);
  if (ret < 0)
    {
      verr("VIDIOC_STREAMON failed: %d\n", ret);
      goto err_out;
    }
  else
    {
      pcam->loopstate = NXCAMERA_STATE_STREAMING;
    }

  /* Loop until we specifically break. streaming == true means that we are
   * still looping waiting for the stream to complete.  All of the data
   * may have been sent, but the stream is not complete until we get
   * VIDEO_MSG_STOP message
   *
   * The normal protocol for looping errors detected by the video driver
   * is as follows:
   *
   * (1) The video driver will indicated the error by returning a negated
   *     error value when the next buffer is enqueued.  The upper level
   *     then knows that this buffer was not queued.
   * (2) The video driver must return all queued buffers using the
   *     VIDEO_MSG_DEQUEUE message.
   */

  /* Open output file before the loop (video mode uses append) */

  if (pcam->videopath[0] != '\0')
    {
      output_fd = open(pcam->videopath,
                       O_WRONLY | O_CREAT | O_APPEND, 0644);
    }
  else if (pcam->imagepath[0] != '\0')
    {
      output_fd = open(pcam->imagepath,
                       O_WRONLY | O_CREAT | O_TRUNC, 0644);
    }

  vinfo("output_fd=%d videopath=%s imagepath=%s\n",
        output_fd, pcam->videopath, pcam->imagepath);

  while (streaming)
    {
      size = mq_receive(pcam->mq, (FAR char *)&msg, sizeof(msg), &prio);

      /* Validate a message was received */

      if (size == sizeof(msg))
        {
          /* Perform operation based on message id */

          vinfo("message received size %zd id%d\n", size, msg.msg_id);
          switch (msg.msg_id)
            {
              /* Someone wants to stop the stream. */

              case VIDEO_MSG_STOP:

                /* Send a stop message to the device */

                vinfo("Stopping looping\n");
                ioctl(pcam->capture_fd, VIDIOC_STREAMOFF, (uintptr_t)&type);
                streaming = false;
                goto err_out;

              /* Unknown / unsupported message ID */

              default:
                break;
            }
        }

      ret = ioctl(pcam->capture_fd, VIDIOC_DQBUF, (uintptr_t)&buf);
      if (ret < 0)
        {
          verr("Fail DQBUF %d\n", errno);
          goto err_out;
        }

      if (buf.index >= pcam->nbuffers)
        {
          verr("Invalid buf.index %d\n", buf.index);
          goto err_out;
        }

      /* Write frame to file if output file is configured */

      if (output_fd >= 0)
        {
          uint32_t frame_size;

          frame_size = buf.bytesused > 0 ?
                       buf.bytesused : pcam->buf_sizes[buf.index];

          ret = write(output_fd, pcam->bufs[buf.index], frame_size);
          if (ret != frame_size)
            {
              verr("write failed: ret=%d frame_size=%" PRIu32
                   " errno=%d\n", ret, frame_size, errno);
            }

          /* Stop after max_frames if specified (0=unlimited) */

          if (pcam->max_frames > 0)
            {
              pcam->max_frames--;
              if (pcam->max_frames == 0)
                {
                  streaming = false;
                  continue;
                }
            }
        }
      else
        {
          ret = show_image(pcam, &buf);
          if (ret < 0)
            {
              verr("Fail to show image %d\n", -ret);
              goto err_out;
            }

          if (pcam->display_pinfo.yres_virtual >
              pcam->display_vinfo.yres)
            {
              pan_display(pcam->display_fd,
                          &pcam->display_pinfo);
            }
        }

      ret = ioctl(pcam->capture_fd, VIDIOC_QBUF, (uintptr_t)&buf);
      if (ret < 0)
        {
          verr("Fail QBUF %d\n", errno);
          goto err_out;
        }
    }

  /* Release our video buffers and unregister / release the device */

err_out:
  vinfo("Clean-up and exit\n");

  /* Close output file if open */

  if (output_fd >= 0)
    {
      close(output_fd);
    }

  /* Cleanup */

  pthread_mutex_lock(&pcam->mutex);  /* Lock the mutex */

  close(pcam->display_fd);           /* Close the display device */
  close(pcam->capture_fd);           /* Close the capture device */
  pcam->display_fd = -1;             /* Mark display device as closed */
  pcam->capture_fd = -1;             /* Mark capture device as closed */
  mq_close(pcam->mq);                /* Close the message queue */
  mq_unlink(pcam->mqname);           /* Unlink the message queue */
  pcam->loopstate = NXCAMERA_STATE_IDLE;
  for (i = 0; i < pcam->nbuffers; i++)
    {
      munmap(pcam->bufs[i], pcam->buf_sizes[i]);
    }

  free(pcam->bufs);
  free(pcam->buf_sizes);
  pthread_mutex_unlock(&pcam->mutex);     /* Unlock the mutex */

  vinfo("Exit\n");

  return NULL;

  return OK;
}

/****************************************************************************
 * Name: nxcamera_stop
 *
 *   nxcamera_stop() stops the current playback to loop and closes the
 *   file and the associated device.
 *
 * Input:
 *   pcam    Pointer to the initialized looper context
 *
 ****************************************************************************/

int nxcamera_stop(FAR struct nxcamera_s *pcam)
{
  struct video_msg_s term_msg;

  DEBUGASSERT(pcam != NULL);

  /* Validate we are not in IDLE state */

  pthread_mutex_lock(&pcam->mutex);          /* Lock the mutex */
  if (pcam->loopstate == NXCAMERA_STATE_IDLE)
    {
      pthread_mutex_unlock(&pcam->mutex);    /* Unlock the mutex */
      return OK;
    }

  /* Notify the stream thread that it needs to cancel the stream */

  term_msg.msg_id = VIDEO_MSG_STOP;
  term_msg.u.data = 0;
  mq_send(pcam->mq, (FAR const char *)&term_msg, sizeof(term_msg),
          CONFIG_NXCAMERA_MSG_PRIO);

  pthread_mutex_unlock(&pcam->mutex);

  /* Join the thread.  The thread will do all the cleanup. */

  nxcamera_jointhread(pcam);

  return OK;
}

/****************************************************************************
 * Name: nxcamera_stream
 *
 *   nxcamera_stream() tries to capture and then display the raw data using
 *   the Video system. If a capture device is specified, it will try to use
 *   that device.
 *
 * Input:
 *   pcam    Pointer to the initialized Looper context
 *   width      Capture frame width
 *   height     Capture frame height
 *   framerate  Capture frame rate
 *   format     Capture frame pixel format
 *
 * Returns:

static int capture_dqbuf(FAR struct file *filep,
                         FAR struct v4l2_buffer *buf)
{
  FAR struct inode *inode = filep->f_inode;
  FAR capture_mng_t *cmng = inode->i_private;
  FAR capture_type_inf_t *type_inf;
  FAR vbuf_container_t *container;
  FAR sem_t *dqbuf_wait_flg;
  enum capture_state_e next_capture_state;

  if (cmng == NULL || buf == NULL)
    {
      return -EINVAL;
    }

  type_inf = get_capture_type_inf(cmng, buf->type);
  if (type_inf == NULL)
    {
      return -EINVAL;
    }

  container = video_framebuff_dq_valid_container(&type_inf->bufinf);
  if (container == NULL)
    {
      if (filep->f_oflags & O_NONBLOCK)
        {
          return -EAGAIN;
        }

      /* Not yet done capture. Wait done */

      dqbuf_wait_flg = &type_inf->wait_capture.dqbuf_wait_flg;

      /* Loop until semaphore is unlocked by capture done or DQCANCEL */

      do
        {
          if (buf->type == V4L2_BUF_TYPE_VIDEO_CAPTURE)
            {
              /* If start capture condition is satisfied, start capture */

              nxmutex_lock(&cmng->mutex);
              next_capture_state =
                estimate_next_capture_state(cmng, CAUSE_CAPTURE_DQBUF);
              change_capture_state(cmng, next_capture_state);
              nxmutex_unlock(&cmng->mutex);
            }

          nxsem_wait_uninterruptible(dqbuf_wait_flg);
        }
      while (type_inf->wait_capture.waitend_cause ==
             WAITEND_CAUSE_STILLSTOP);

      container = type_inf->wait_capture.done_container;
      if (container == NULL)
        {
          /* Waking up without captured data means abort.
           * Therefore, Check cause.
           */

          DEBUGASSERT(type_inf->wait_capture.waitend_cause ==
                      WAITEND_CAUSE_DQCANCEL);
          return -ECANCELED;
        }

      type_inf->wait_capture.done_container = NULL;
    }

  memcpy(buf, &container->buf, sizeof(struct v4l2_buffer));
  video_framebuff_free_container(&type_inf->bufinf, container);

  return OK;
}

static int capture_cancel_dqbuf(FAR struct file *filep,
                                enum v4l2_buf_type type)
{
  FAR struct inode *inode = filep->f_inode;
  FAR capture_mng_t *cmng = inode->i_private;
  FAR capture_type_inf_t *type_inf;

  if (cmng == NULL)
    {
      return -EINVAL;
    }

  type_inf = get_capture_type_inf(cmng, type);
  if (type_inf == NULL)
    {
      return -EINVAL;
    }

  if (!is_sem_waited(&type_inf->wait_capture.dqbuf_wait_flg))
    {
      /* In not waiting DQBUF case, return OK */

      return OK;
    }

  type_inf->wait_capture.waitend_cause = WAITEND_CAUSE_DQCANCEL;

  /* If capture is done before nxsem_post, cause is overwritten */

  return nxsem_post(&type_inf->wait_capture.dqbuf_wait_flg);
}

static int capture_g_fmt(FAR struct file *filep,
                         FAR struct v4l2_format *fmt)
{

/****************************************************************************
 * board/beken/chips/bk7258/bk7258_camera_imgdata.c
 *
 * BK7258 GC2145 camera platform (imgdata) driver: NuttX V4L2
 * imgdata_ops_s implementation for the YUV_BUF + generic-DMA capture
 * path.  This is the platform data interface half of the driver split
 * described in the openvela Camera Driver Framework guide -- it owns
 * the frame buffer, the ping-pong-bank-to-DMA-copy plumbing, and
 * full-frame assembly across the line-batch-done interrupts needed to
 * fill one frame.  Sensor-specific I2C register programming lives in
 * the imgsensor half
 * (board/beken/boards/bk7258/bk7258-ap/src/bk7258_camera_imgsensor.c).
 *
 * Full-frame assembly:
 *   YUV_BUF's PSRAM line buffer is two adjacent ping-pong regions
 *   (bk7258_yuv_buf_get_line_buf_addr(), each
 *   bk7258_yuv_buf_get_line_batch_bytes() bytes), holding 8 lines of
 *   YUYV data each.  The hardware alternates writing into the two
 *   regions and fires SM0_WR/SM1_WR accordingly.  On each bank-done
 *   callback, this driver issues one DMA copy from that bank's fixed
 *   PSRAM address to (frame_buf + frame_offset), then advances
 *   frame_offset by one batch.  Once frame_offset reaches the frame
 *   size, the imgdata_capture_t callback reports one complete frame
 *   and frame_offset resets to 0.
 *
 * Each DMA copy must complete before the hardware's next occurrence of
 * that same bank arrives; this driver does not block waiting for DMA
 * completion in the bank-done callback (mirroring the reference
 * implementation's non-blocking DMA start pattern).
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>

#include <sys/time.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <errno.h>

#include <nuttx/video/imgdata.h>

#include "bk7258_yuv_buf.h"
#include "bk7258_dma.h"
#include "bk7258_camera_imgdata.h"
#include "bk7258_psram.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* This driver only supports the one resolution/format the GC2145
 * register tables in the imgsensor half produce.
 */

#define BK7258_CAMERA_WIDTH   640u
#define BK7258_CAMERA_HEIGHT  480u
#define BK7258_CAMERA_FRAME_BYTES \
  (BK7258_CAMERA_WIDTH * BK7258_CAMERA_HEIGHT * 2u) /* YUYV, 2 bytes/px */

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct bk7258_camera_imgdata_s
{
  struct imgdata_s data;          /* Must be first: base-pointer cast. */
  FAR uint8_t *frame_buf;          /* Set by set_buf(); NULL until then. */
  uint32_t frame_buf_size;
  uint32_t frame_offset;           /* Bytes assembled so far. */
  bool capturing;
  imgdata_capture_t capture_cb;
  FAR void *capture_cb_arg;
};

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

static int bk7258_camera_imgdata_init(FAR struct imgdata_s *data);
static int bk7258_camera_imgdata_uninit(FAR struct imgdata_s *data);
static int bk7258_camera_imgdata_set_buf(FAR struct imgdata_s *data,
                                          uint8_t nr_datafmts,
                                          FAR imgdata_format_t *datafmts,
                                          uint8_t *addr, uint32_t size);
static int bk7258_camera_imgdata_validate_frame_setting(
    FAR struct imgdata_s *data, uint8_t nr_datafmts,
    FAR imgdata_format_t *datafmts, FAR imgdata_interval_t *interval);
static int bk7258_camera_imgdata_start_capture(
    FAR struct imgdata_s *data, uint8_t nr_datafmts,
    FAR imgdata_format_t *datafmts, FAR imgdata_interval_t *interval,
    imgdata_capture_t callback, FAR void *arg);
static int bk7258_camera_imgdata_stop_capture(FAR struct imgdata_s *data);
static void *bk7258_camera_imgdata_alloc(FAR struct imgdata_s *data,
                                          uint32_t align_size,
                                          uint32_t size);
static void bk7258_camera_imgdata_free(FAR struct imgdata_s *data,
                                        void *addr);

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const struct imgdata_ops_s g_bk7258_camera_imgdata_ops =
{
  .init                   = bk7258_camera_imgdata_init,
  .uninit                 = bk7258_camera_imgdata_uninit,
  .set_buf                = bk7258_camera_imgdata_set_buf,
  .validate_frame_setting = bk7258_camera_imgdata_validate_frame_setting,
  .start_capture          = bk7258_camera_imgdata_start_capture,
  .stop_capture           = bk7258_camera_imgdata_stop_capture,
  .alloc                  = bk7258_camera_imgdata_alloc,
  .free                   = bk7258_camera_imgdata_free,
};

static struct bk7258_camera_imgdata_s g_bk7258_camera_imgdata =
{
  .data = { &g_bk7258_camera_imgdata_ops },
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bk7258_camera_line_batch_done
 *
 * Description:
 *   YUV_BUF ping-pong bank-done callback (ISR context, one call per
 *   8-line batch).  Issues one DMA copy of that bank's fixed PSRAM
 *   contents into the frame buffer at the current running offset, then
 *   advances the offset.  Reports frame completion once a full frame
 *   has been assembled.
 *
 ****************************************************************************/

static void bk7258_camera_line_batch_done(bk7258_yuv_buf_bank_t bank,
                                           FAR void *arg)
{
  FAR struct bk7258_camera_imgdata_s *priv = arg;
  uint32_t line_buf_addr = bk7258_yuv_buf_get_line_buf_addr();
  uint32_t batch_bytes = bk7258_yuv_buf_get_line_batch_bytes();
  uint32_t src_addr;
  struct timeval ts;

  if (!priv->capturing || priv->frame_buf == NULL)
    {
      printf("bk7258_camera_imgdata: line_batch_done: bank=%d ignored "
             "(capturing=%d frame_buf=%p)\n",
             (int)bank, (int)priv->capturing, priv->frame_buf);
      return;
    }

  if (priv->frame_offset + batch_bytes > priv->frame_buf_size)
    {
      /* Should not happen once validate_frame_setting()/set_buf() have
       * agreed on BK7258_CAMERA_FRAME_BYTES; drop this batch and
       * resynchronize at the next frame boundary rather than writing
       * past the buffer.
       */

      printf("bk7258_camera_imgdata: line_batch_done: offset overflow, "
             "offset=%u batch_bytes=%u buf_size=%u, resyncing\n",
             (unsigned int)priv->frame_offset, (unsigned int)batch_bytes,
             (unsigned int)priv->frame_buf_size);
      priv->frame_offset = 0;
      return;
    }

  src_addr = line_buf_addr;
  if (bank == BK7258_YUV_BUF_BANK_SM1)
    {
      src_addr += batch_bytes;
    }

  printf("bk7258_camera_imgdata: line_batch_done: bank=%s src=0x%08x "
         "dst=0x%08x len=%u offset=%u/%u\n",
         bank == BK7258_YUV_BUF_BANK_SM0 ? "SM0" : "SM1",
         (unsigned int)src_addr,
         (unsigned int)(uintptr_t)(priv->frame_buf + priv->frame_offset),
         (unsigned int)batch_bytes, (unsigned int)priv->frame_offset,
         (unsigned int)priv->frame_buf_size);

  bk7258_dma_configure(src_addr,
                        (uint32_t)(uintptr_t)(priv->frame_buf +
                                               priv->frame_offset),
                        batch_bytes);
  bk7258_dma_start();

  priv->frame_offset += batch_bytes;

  if (priv->frame_offset >= priv->frame_buf_size)
    {
      priv->frame_offset = 0;

      printf("bk7258_camera_imgdata: frame complete, %u bytes\n",
             (unsigned int)priv->frame_buf_size);

      if (priv->capture_cb != NULL)
        {
          gettimeofday(&ts, NULL);
          priv->capture_cb(OK, priv->frame_buf_size, &ts,
                            priv->capture_cb_arg);
        }
    }
}

static int bk7258_camera_imgdata_init(FAR struct imgdata_s *data)
{
  FAR struct bk7258_camera_imgdata_s *priv =
      (FAR struct bk7258_camera_imgdata_s *)data;

  printf("bk7258_camera_imgdata: init: entry\n");

  bk7258_yuv_buf_init();
  bk7258_dma_init();
  bk7258_yuv_buf_set_line_callback(bk7258_camera_line_batch_done, priv);

  printf("bk7258_camera_imgdata: init: complete\n");

  return OK;
}

static int bk7258_camera_imgdata_uninit(FAR struct imgdata_s *data)
{
  printf("bk7258_camera_imgdata: uninit\n");

  bk7258_yuv_buf_stop();
  bk7258_dma_stop();
  bk7258_yuv_buf_set_line_callback(NULL, NULL);

  return OK;
}

static int bk7258_camera_imgdata_set_buf(FAR struct imgdata_s *data,
                                          uint8_t nr_datafmts,
                                          FAR imgdata_format_t *datafmts,
                                          uint8_t *addr, uint32_t size)
{
  FAR struct bk7258_camera_imgdata_s *priv =
      (FAR struct bk7258_camera_imgdata_s *)data;

  if (size < BK7258_CAMERA_FRAME_BYTES)
    {
      printf("bk7258_camera_imgdata: set_buf: size %u < required %u, "
             "-EINVAL\n", (unsigned int)size,
             (unsigned int)BK7258_CAMERA_FRAME_BYTES);
      return -EINVAL;
    }

  priv->frame_buf = addr;
  priv->frame_buf_size = BK7258_CAMERA_FRAME_BYTES;
  priv->frame_offset = 0;

  printf("bk7258_camera_imgdata: set_buf: addr=%p size=%u "
         "(buffer size given=%u)\n",
         addr, (unsigned int)priv->frame_buf_size, (unsigned int)size);

  return OK;
}

static int bk7258_camera_imgdata_validate_frame_setting(
    FAR struct imgdata_s *data, uint8_t nr_datafmts,
    FAR imgdata_format_t *datafmts, FAR imgdata_interval_t *interval)
{
  if (nr_datafmts < 1)
    {
      return -EINVAL;
    }

  if (datafmts[IMGDATA_FMT_MAIN].width != BK7258_CAMERA_WIDTH ||
      datafmts[IMGDATA_FMT_MAIN].height != BK7258_CAMERA_HEIGHT ||
      datafmts[IMGDATA_FMT_MAIN].pixelformat != IMGDATA_PIX_FMT_YUYV)
    {
      return -EINVAL;
    }

  return OK;
}

static int bk7258_camera_imgdata_start_capture(
    FAR struct imgdata_s *data, uint8_t nr_datafmts,
    FAR imgdata_format_t *datafmts, FAR imgdata_interval_t *interval,
    imgdata_capture_t callback, FAR void *arg)
{
  FAR struct bk7258_camera_imgdata_s *priv =
      (FAR struct bk7258_camera_imgdata_s *)data;
  int ret;

  printf("bk7258_camera_imgdata: start_capture: entry, frame_buf=%p "
         "frame_buf_size=%u\n", priv->frame_buf,
         (unsigned int)priv->frame_buf_size);

  ret = bk7258_camera_imgdata_validate_frame_setting(data, nr_datafmts,
                                                      datafmts, interval);
  if (ret < 0)
    {
      printf("bk7258_camera_imgdata: start_capture: validate failed, "
             "ret=%d\n", ret);
      return ret;
    }

  if (priv->frame_buf == NULL)
    {
      printf("bk7258_camera_imgdata: start_capture: frame_buf is NULL, "
             "-EINVAL\n");
      return -EINVAL;
    }

  priv->capture_cb = callback;
  priv->capture_cb_arg = arg;
  priv->frame_offset = 0;
  priv->capturing = true;

  bk7258_yuv_buf_dump_status("start_capture: before configure");

  bk7258_yuv_buf_configure(BK7258_CAMERA_WIDTH, BK7258_CAMERA_HEIGHT);
  bk7258_yuv_buf_start();

  /* Diagnostic snapshots after start: does not block waiting for a
   * frame (that would risk the same DQBUF-style stall this diagnostic
   * exists to avoid), just samples int_status/isr_fire_count a few
   * times over ~600ms so the serial log has a record of whether any
   * interrupt activity occurred shortly after start, even if the
   * caller's own DQBUF loop later stalls waiting for a frame that
   * never completes.
   */

  up_mdelay(200);
  bk7258_yuv_buf_dump_status("start_capture: +200ms");
  up_mdelay(200);
  bk7258_yuv_buf_dump_status("start_capture: +400ms");
  up_mdelay(200);
  bk7258_yuv_buf_dump_status("start_capture: +600ms");

  printf("bk7258_camera_imgdata: start_capture: complete\n");

  return OK;
}

static int bk7258_camera_imgdata_stop_capture(FAR struct imgdata_s *data)
{
  FAR struct bk7258_camera_imgdata_s *priv =
      (FAR struct bk7258_camera_imgdata_s *)data;

  printf("bk7258_camera_imgdata: stop_capture: frame_offset=%u/%u\n",
         (unsigned int)priv->frame_offset,
         (unsigned int)priv->frame_buf_size);

  priv->capturing = false;
  bk7258_yuv_buf_stop();
  bk7258_dma_stop();

  return OK;
}

/* V4L2_REQBUFS_COUNT_MAX (3) capture buffers at one 640x480 YUYV frame
 * (614400 bytes) exceed this board's internal SRAM heap
 * (CONFIG_RAM_SIZE=344064 bytes), so the framework's default
 * kumm_memalign()-backed allocation cannot hold the buffer pool.  This
 * board has a separate 16MB PSRAM region not mapped into the kernel's
 * malloc arena; imgdata_ops_s.alloc/free (the framework's documented
 * mechanism for drivers whose buffers must come from a non-default
 * memory pool) routes allocation to bk7258_psram.c's
 * bk7258_media_pool_alloc()/_free() instead.
 */

static void *bk7258_camera_imgdata_alloc(FAR struct imgdata_s *data,
                                          uint32_t align_size,
                                          uint32_t size)
{
  return bk7258_media_pool_alloc(BK7258_PSRAM_POOL_DISPLAY,
                                  align_size, size);
}

static void bk7258_camera_imgdata_free(FAR struct imgdata_s *data,
                                        void *addr)
{
  bk7258_media_pool_free(BK7258_PSRAM_POOL_DISPLAY, addr);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

FAR struct imgdata_s *bk7258_camera_imgdata_initialize(void)
{
  return &g_bk7258_camera_imgdata.data;
}

/****************************************************************************
 * board/beken/chips/bk7258/bk7258_yuv_buf.c
 *
 * BK7258 YUV_BUF controller, YUV direct-capture mode only.  Register
 * layout source: bk_avdk_smp release/v3.1.1
 * ap/middleware/soc/bk7258_ap/soc/yuv_buf_struct.h and
 * ap/middleware/soc/bk7258_ap/hal/yuv_buf_ll.h.
 *
 * Register map (byte offset from BK7258_YUV_BUF_BASE):
 *   global_ctrl   0x08 - bit[0] soft_reset, bit[1] clk_gate_bypass
 *   ctrl          0x10 - bit[0] yuv_mode, bit[2:3] yuv_fmt_sel,
 *                         bit[6] hsync_rev, bit[7] vsync_rev,
 *                         bit[9] sync_edge_dect_en, bit[10:11] mclk_div,
 *                         bit[12] h264_mode, bit[13] bps_cis,
 *                         bit[14] memrev, bit[19] soi_hsync
 *   pixel         0x14 - bit[0:7] x_pixel, bit[8:15] y_pixel,
 *                         bit[16:31] frame_blk
 *   em_base_addr  0x20
 *   int_en        0x24 - bit[2] sm0_wr_int_en, bit[3] sm1_wr_int_en
 *   int_status    0x28 - bit[2] sm0_wr_int, bit[3] sm1_wr_int
 *                         (write-1-to-clear)
 *   emr_base_addr 0x30
 *   resize_pixel  0x34 - bit[1:8] x_pixel, bit[9:16] y_pixel
 *
 * x_pixel/y_pixel are width/height divided by 8 (matching bk_dvp.c's
 * "yuv_mode_config.x_pixel = config->width / 8"); frame_blk = x_pixel *
 * y_pixel / 2.  YUV direct-capture mode hard-codes em_base_addr/
 * emr_base_addr to SOC_PSRAM_DATA_BASE rather than an
 * application-supplied address (ap/middleware/soc/common/hal/
 * yuv_buf_hal.c yuv_buf_hal_set_yuv_mode_config()).
 *
 * Power/clock: enabling this module requires clearing the video
 * pipeline's shared power-down bit and setting its own clock gate,
 * both in the system controller's register space
 * (ap/middleware/driver/yuv_buf/yuv_buf_driver.c
 * yuv_buf_init_common()) -- neither is part of YUV_BUF's own register
 * block.  bk_avdk_smp enables the H264 clock gate alongside YUV_BUF's
 * even for pure YUV direct-capture mode; both are set here to match.
 *
 * Interrupt: single line (INT_SRC_YUVB / BK7258_IRQ_YUVB) multiplexing
 * several event bits in int_status; only sm0_wr/sm1_wr (line-batch-done,
 * fired every 8 lines as the hardware alternates between its two
 * ping-pong PSRAM regions) are consumed here.  Full-frame assembly
 * across the ~60 line-batch-done events needed for one frame is the
 * caller's responsibility -- see bk7258_camera_imgdata.c.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/irq.h>
#include <stdint.h>
#include <stdio.h>

#include "arm_internal.h"
#include "hardware/bk7258_memorymap.h"
#include "irq.h"
#include "bk7258_yuv_buf.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define BK7258_YUV_BUF_BASE        0x48020000u  /* SOC_YUV_BUF_REG_BASE */

#define YUV_BUF_REG(word_off)      (BK7258_YUV_BUF_BASE + (word_off) * 4u)

#define YUV_BUF_GLOBAL_CTRL              YUV_BUF_REG(2)
#define YUV_BUF_GLOBAL_CTRL_SOFT_RESET   (1u << 0)
#define YUV_BUF_GLOBAL_CTRL_CLK_GATE_BYPASS (1u << 1)

#define YUV_BUF_CTRL                     YUV_BUF_REG(4)
#define YUV_BUF_CTRL_YUV_MODE            (1u << 0)
#define YUV_BUF_CTRL_YUV_FMT_SEL_SHIFT   2u
#define YUV_BUF_CTRL_YUV_FMT_SEL_MASK    (0x3u << YUV_BUF_CTRL_YUV_FMT_SEL_SHIFT)
#define YUV_BUF_CTRL_HSYNC_REV           (1u << 6)
#define YUV_BUF_CTRL_VSYNC_REV           (1u << 7)
#define YUV_BUF_CTRL_SYNC_EDGE_DECT_EN   (1u << 9)
#define YUV_BUF_CTRL_MCLK_DIV_SHIFT      10u
#define YUV_BUF_CTRL_MCLK_DIV_MASK       (0x3u << YUV_BUF_CTRL_MCLK_DIV_SHIFT)
#define YUV_BUF_CTRL_H264_MODE           (1u << 12)
#define YUV_BUF_CTRL_BPS_CIS             (1u << 13)
#define YUV_BUF_CTRL_MEMREV              (1u << 14)
#define YUV_BUF_CTRL_SOI_HSYNC           (1u << 19)

#define YUV_BUF_FMT_YUYV                 0u
#define YUV_BUF_MCLK_DIV_3               3u

#define YUV_BUF_PIXEL                    YUV_BUF_REG(5)
#define YUV_BUF_PIXEL_X_SHIFT            0u
#define YUV_BUF_PIXEL_Y_SHIFT            8u
#define YUV_BUF_PIXEL_FRAME_BLK_SHIFT    16u

#define YUV_BUF_EM_BASE_ADDR             YUV_BUF_REG(8)
#define YUV_BUF_INT_EN                   YUV_BUF_REG(9)
#define YUV_BUF_INT_EN_ALL               0x1FFu

#define YUV_BUF_INT_STATUS               YUV_BUF_REG(10)
#define YUV_BUF_INT_STATUS_SM0_WR        (1u << 2)
#define YUV_BUF_INT_STATUS_SM1_WR        (1u << 3)

#define YUV_BUF_EMR_BASE_ADDR            YUV_BUF_REG(12)

#define YUV_BUF_RESIZE_PIXEL             YUV_BUF_REG(13)
#define YUV_BUF_RESIZE_PIXEL_X_SHIFT     1u
#define YUV_BUF_RESIZE_PIXEL_Y_SHIFT     9u

/* SOC_PSRAM_DATA_BASE, ap/include/soc/bk7258/reg_base.h. */

#define YUV_BUF_PSRAM_LINE_BUF_ADDR      0x60000000u

/* System controller registers (SOC_SYS_REG_BASE) that gate the video
 * pipeline's power and this module's clock -- required before any of
 * YUV_BUF's own registers have real effect.  Ported from
 * yuv_buf_init_common(); see file header.
 */

#define BK7258_SYS_REG_BASE              0x44010000u
#define BK7258_SYS_REG_0X10               (BK7258_SYS_REG_BASE + (0x10u << 2))
#define BK7258_SYS_PWD_VIDP                (1u << 7)

#define BK7258_SYS_REG_0X0D               (BK7258_SYS_REG_BASE + (0xdu << 2))
#define BK7258_SYS_YUV_CKEN                 (1u << 3)
#define BK7258_SYS_H264_CKEN                (1u << 0)

/****************************************************************************
 * Private Data
 ****************************************************************************/

static bk7258_yuv_buf_line_cb_t g_line_cb;
static void *g_line_cb_arg;
static uint32_t g_line_batch_bytes;
static uint32_t g_isr_fire_count;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static int bk7258_yuv_buf_isr(int irq, void *context, void *arg)
{
  uint32_t status = getreg32(YUV_BUF_INT_STATUS);

  g_isr_fire_count++;
  printf("bk7258_yuv_buf: ISR fired #%u int_status=0x%08x\n",
         (unsigned int)g_isr_fire_count, (unsigned int)status);

  /* Write-1-to-clear: write back exactly the bits read as set. */

  putreg32(status, YUV_BUF_INT_STATUS);

  if (g_line_cb != NULL)
    {
      if ((status & YUV_BUF_INT_STATUS_SM0_WR) != 0)
        {
          g_line_cb(BK7258_YUV_BUF_BANK_SM0, g_line_cb_arg);
        }

      if ((status & YUV_BUF_INT_STATUS_SM1_WR) != 0)
        {
          g_line_cb(BK7258_YUV_BUF_BANK_SM1, g_line_cb_arg);
        }
    }

  return 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

void bk7258_yuv_buf_init(void)
{
  uint32_t reg;

  /* Power on the video pipeline and enable YUV_BUF's (and H264's,
   * required alongside it even for direct-capture mode) clock gate
   * before touching this module's own registers.
   */

  reg = getreg32(BK7258_SYS_REG_0X10);
  reg &= ~BK7258_SYS_PWD_VIDP;
  putreg32(reg, BK7258_SYS_REG_0X10);

  reg = getreg32(BK7258_SYS_REG_0X0D);
  reg |= BK7258_SYS_H264_CKEN | BK7258_SYS_YUV_CKEN;
  putreg32(reg, BK7258_SYS_REG_0X0D);

  printf("bk7258_yuv_buf: init: power/clock enabled, reg0x10=0x%08x "
         "reg0x0d=0x%08x\n",
         (unsigned int)getreg32(BK7258_SYS_REG_0X10),
         (unsigned int)getreg32(BK7258_SYS_REG_0X0D));

  /* Global control: soft_reset is active-low per the reference
   * implementation's yuv_buf_ll_global_soft_reset_enable()/_disable()
   * naming (enable() writes 0, disable() writes 1) and
   * yuv_buf_ll_init()'s pulse (0, then 1, ending at 1) -- but THREE
   * independent attempts on this specific board (two documented in
   * docs/main/2026-08-07-global-ctrl-polarity-hang-and-further-
   * elimination.md, plus this session's attempt which also produced
   * zero diagnostic output before a full AP-core hang and CP-side IPC
   * heartbeat timeout / mb_ipc_task assert) have now reproduced the
   * exact same whole-system hang.  This is DISPROVEN on this hardware
   * revision despite matching the reference source's literal
   * semantics -- reverted to the original polarity (write 1, delay,
   * write 0 -- ends at 0) that has never hung the system.  Per this
   * project's methodology, do not attempt a fourth variant of this
   * same register write without independent hardware evidence
   * (oscilloscope/JTAG register trace); trial-and-error on this
   * specific bit has now cost three AP-core hangs.
   */

  putreg32(YUV_BUF_GLOBAL_CTRL_SOFT_RESET, YUV_BUF_GLOBAL_CTRL);
  up_udelay(10);
  putreg32(0, YUV_BUF_GLOBAL_CTRL);

  printf("bk7258_yuv_buf: init: global_ctrl=0x%08x (soft-reset pulse "
         "complete, reverted to original polarity per prior hang "
         "evidence)\n", (unsigned int)getreg32(YUV_BUF_GLOBAL_CTRL));

  irq_attach(BK7258_IRQ_YUVB, bk7258_yuv_buf_isr, NULL);
  up_enable_irq(BK7258_IRQ_YUVB);

  printf("bk7258_yuv_buf: init: complete, irq=%d attached and enabled\n",
         (int)BK7258_IRQ_YUVB);
}

void bk7258_yuv_buf_configure(uint16_t width, uint16_t height)
{
  uint32_t x_pixel = width / 8u;
  uint32_t y_pixel = height / 8u;
  uint32_t frame_blk = (x_pixel * y_pixel) / 2u;
  uint32_t ctrl;

  g_line_batch_bytes = (uint32_t)width * 8u * 2u; /* 8 lines, YUV422 */

  putreg32((x_pixel << YUV_BUF_PIXEL_X_SHIFT) |
           (y_pixel << YUV_BUF_PIXEL_Y_SHIFT) |
           (frame_blk << YUV_BUF_PIXEL_FRAME_BLK_SHIFT),
           YUV_BUF_PIXEL);

  ctrl = getreg32(YUV_BUF_CTRL);
  ctrl &= ~(YUV_BUF_CTRL_YUV_FMT_SEL_MASK | YUV_BUF_CTRL_HSYNC_REV |
            YUV_BUF_CTRL_VSYNC_REV | YUV_BUF_CTRL_MCLK_DIV_MASK |
            YUV_BUF_CTRL_BPS_CIS | YUV_BUF_CTRL_MEMREV);
  ctrl |= (YUV_BUF_FMT_YUYV << YUV_BUF_CTRL_YUV_FMT_SEL_SHIFT);
  ctrl |= YUV_BUF_CTRL_SYNC_EDGE_DECT_EN;
  ctrl |= (YUV_BUF_MCLK_DIV_3 << YUV_BUF_CTRL_MCLK_DIV_SHIFT);
  ctrl |= YUV_BUF_CTRL_SOI_HSYNC;
  putreg32(ctrl, YUV_BUF_CTRL);

  putreg32((x_pixel << YUV_BUF_RESIZE_PIXEL_X_SHIFT) |
           (y_pixel << YUV_BUF_RESIZE_PIXEL_Y_SHIFT),
           YUV_BUF_RESIZE_PIXEL);

  putreg32(YUV_BUF_PSRAM_LINE_BUF_ADDR, YUV_BUF_EM_BASE_ADDR);
  putreg32(YUV_BUF_PSRAM_LINE_BUF_ADDR, YUV_BUF_EMR_BASE_ADDR);

  putreg32(YUV_BUF_INT_EN_ALL, YUV_BUF_INT_EN);

  printf("bk7258_yuv_buf: configure(%ux%u): x_pixel=%u y_pixel=%u "
         "line_batch_bytes=%u\n",
         (unsigned int)width, (unsigned int)height,
         (unsigned int)x_pixel, (unsigned int)y_pixel,
         (unsigned int)g_line_batch_bytes);
  printf("bk7258_yuv_buf: configure: global_ctrl=0x%08x ctrl=0x%08x "
         "pixel=0x%08x resize_pixel=0x%08x int_en=0x%08x "
         "em_base_addr=0x%08x emr_base_addr=0x%08x\n",
         (unsigned int)getreg32(YUV_BUF_GLOBAL_CTRL),
         (unsigned int)getreg32(YUV_BUF_CTRL),
         (unsigned int)getreg32(YUV_BUF_PIXEL),
         (unsigned int)getreg32(YUV_BUF_RESIZE_PIXEL),
         (unsigned int)getreg32(YUV_BUF_INT_EN),
         (unsigned int)getreg32(YUV_BUF_EM_BASE_ADDR),
         (unsigned int)getreg32(YUV_BUF_EMR_BASE_ADDR));
}

uint32_t bk7258_yuv_buf_get_line_buf_addr(void)
{
  return YUV_BUF_PSRAM_LINE_BUF_ADDR;
}

uint32_t bk7258_yuv_buf_get_line_batch_bytes(void)
{
  return g_line_batch_bytes;
}

void bk7258_yuv_buf_set_line_callback(bk7258_yuv_buf_line_cb_t cb, void *arg)
{
  g_line_cb = cb;
  g_line_cb_arg = arg;
}

void bk7258_yuv_buf_start(void)
{
  modifyreg32(YUV_BUF_CTRL, YUV_BUF_CTRL_H264_MODE, YUV_BUF_CTRL_YUV_MODE);
  printf("bk7258_yuv_buf: start: ctrl=0x%08x global_ctrl=0x%08x "
         "int_en=0x%08x int_status=0x%08x isr_fire_count=%u\n",
         (unsigned int)getreg32(YUV_BUF_CTRL),
         (unsigned int)getreg32(YUV_BUF_GLOBAL_CTRL),
         (unsigned int)getreg32(YUV_BUF_INT_EN),
         (unsigned int)getreg32(YUV_BUF_INT_STATUS),
         (unsigned int)g_isr_fire_count);
}

void bk7258_yuv_buf_stop(void)
{
  modifyreg32(YUV_BUF_CTRL, YUV_BUF_CTRL_YUV_MODE, 0);
  printf("bk7258_yuv_buf: stop: ctrl=0x%08x isr_fire_count=%u\n",
         (unsigned int)getreg32(YUV_BUF_CTRL),
         (unsigned int)g_isr_fire_count);
}

void bk7258_yuv_buf_dump_status(FAR const char *tag)
{
  printf("bk7258_yuv_buf: [%s] global_ctrl=0x%08x ctrl=0x%08x "
